{{ get_solua_print_css() }}{% set p = get_wholesale_print_data(doc) %}{% set company = p.company %}{% set customer = p.customer %}{% set show_images = 1 if doc.get('custom_print_color_images') is none else doc.get('custom_print_color_images') %}{% set show_item_name = 1 if doc.get('custom_print_item_name') is none else doc.get('custom_print_item_name') %}{% set show_sku = 1 if doc.get('custom_print_sku') is none else doc.get('custom_print_sku') %}{% set show_color_code = 1 if doc.get('custom_print_color_code') is none else doc.get('custom_print_color_code') %}{% set show_cor = 1 if doc.get('custom_print_cor') is none else doc.get('custom_print_cor') %}{% set show_description = 1 if doc.get('custom_print_description') is none else doc.get('custom_print_description') %}{% set ordered_before_setting = 1 if doc.get('custom_print_ordered_before') is none else doc.get('custom_print_ordered_before') %}{% set show_ordered_before = 1 if ordered_before_setting and (p.get('has_ordered_before') or p.get('delivery_quantity_error')) else 0 %}{% set current_remaining_setting = 1 if doc.get('custom_print_current_remaining') is none else doc.get('custom_print_current_remaining') %}{% set traceability_setting = 1 if doc.get('custom_print_traceability') is none else doc.get('custom_print_traceability') %}{% set show_current_remaining = 1 if current_remaining_setting else 0 %}{% set show_traceability = 1 if traceability_setting and p.get('has_traceability') else 0 %}
<h2>Guia de Remessa</h2>
{% if doc.docstatus != 1 %}<div class="warning">{{ 'RASCUNHO / 草稿' if doc.docstatus == 0 else 'CANCELADO / 已取消' }} — Documento não oficial / 非正式凭证</div>{% endif %}
{% if p.get('legacy') %}<div class="warning">Documento histórico sem snapshot de impressão; dados complementares do cadastro atual. / 历史单据未保存打印快照；补充资料来自当前主档。</div>{% endif %}{% if p.get('delivery_quantity_error') %}<div class="warning">{{ p.delivery_quantity_error | e }}</div>{% endif %}
<table class="meta"><tr><td><b>{{ company.name | e }}</b><br>NUIT: {{ company.nuit | e }}<br>{{ company.address }}<br>Tel: {{ company.phone | e }}</td><td><b>Cliente / 客户: {{ customer.name | e }}</b><br>NUIT: {{ customer.nuit or 'Não informado / 未提供' | e }}<br>Loja / 门店: {{ customer.store | e }}<br>{{ customer.address }}<br>{{ customer.contact }} · {{ customer.phone | e }}</td></tr><tr><td>N.º / 编号: {{ doc.name | e }}<br>N.º encomenda cliente / 客户订单号: {{ doc.get('custom_customer_order_no') or '—' | e }}<br>Encomenda / 订单: {{ p.order.name | e }}</td><td>Data / 日期: {{ doc.get('posting_date') or doc.get('transaction_date') }}<br>Saída / 起运: {{ p.transport.departure_time | e }}<br>Endereço do armazém / 仓库地址: {{ p.transport.source_address | e }}</td></tr></table>
<table class="items"><thead><tr><th colspan="{{ 4 + show_images + show_item_name + show_sku + show_color_code + show_cor + show_description + show_ordered_before + show_current_remaining + show_traceability }}">{{ doc.name | e }} · 本次送货 / Entrega</th></tr><tr>{% if show_images %}<th>Foto / 图片</th>{% endif %}{% if show_item_name %}<th>Artigo / 商品</th>{% endif %}{% if show_sku %}<th class="col-sku">SKU / 货号</th>{% endif %}{% if show_color_code %}<th class="col-color-code">Código de cor fixo / 固定色号</th>{% endif %}{% if show_cor %}<th class="col-cor">Cor / 颜色</th>{% endif %}<th class="col-barcode">条码 / Código de barras</th>{% if show_description %}<th class="col-description">描述 / Descrição</th>{% endif %}{% if show_ordered_before %}<th>Quantidade encomendada / 订购数量<br>Entregue anteriormente / 此前已交付</th>{% endif %}{% if show_current_remaining %}<th class="col-qty">Esta entrega / Restante<br>本次 / 剩余</th>{% endif %}<th class="col-uom">Un.</th><th class="col-rate">Preço /<br>单价</th><th class="col-amount">Valor / 金额</th>{% if show_traceability %}<th class="col-traceability">Rastreabilidade / 追溯</th>{% endif %}</tr></thead><tbody>
{% for item in p['items'] %}<tr>{% if show_images %}<td>{% if item.image %}<img class="photo" src="{{ item.image | e }}">{% endif %}</td>{% endif %}{% if show_item_name %}<td>{{ item.item_name | e }}</td>{% endif %}{% if show_sku %}<td class="col-sku">{{ (item.order_code or item.item_code) | e }}</td>{% endif %}{% if show_color_code %}<td class="col-color-code">{{ item.color_code | e }}</td>{% endif %}{% if show_cor %}<td class="col-cor">{{ item.color | e }}</td>{% endif %}<td class="col-barcode">{{ item.barcode | e }}</td>{% if show_description %}<td class="col-description">{{ item.description | e }}</td>{% endif %}{% if show_ordered_before %}<td class='num'>{{ format_print_qty(item.ordered_qty) if item.ordered_qty is not none else '—' }} / {{ format_print_qty(item.delivered_before_qty) if item.delivered_before_qty is not none else '—' }}</td>{% endif %}{% if show_current_remaining %}<td class='col-qty num'>{{ format_print_qty(item.qty) }} / {{ format_print_qty(item.remaining_qty) if item.remaining_qty is not none else '—' }}</td>{% endif %}<td class="col-uom">{{ item.uom | e }}</td><td class="col-rate num">{{ format_print_money(item.rate, currency=doc.currency) }}</td><td class="col-amount num">{{ format_print_money(item.amount, currency=doc.currency) }}</td>{% if show_traceability %}<td class="col-traceability">{{ item.batch_no | e }} {{ item.serial_no | e }} {{ item.serial_and_batch_bundle | e }}</td>{% endif %}</tr>{% endfor %}
</tbody><tfoot><tr><td colspan='{{ 3 + show_images + show_item_name + show_sku + show_color_code + show_cor + show_description + show_ordered_before + show_current_remaining + show_traceability }}' style='text-align:right'><b>Total Qty / 总数量</b></td><td style='text-align:right'><b>{{ format_print_qty(get_print_total_qty(p)) }}</b></td><td colspan='4'></td></tr></tfoot></table><div class="block num">Total / 含税合计: {{ format_print_money(doc.grand_total, currency=doc.currency) }}</div>
<div class="block">Transporte / 运输: {{ p.transport.vehicle_no | e }} · {{ p.transport.driver_name | e }} · {{ p.transport.driver_phone | e }}<br>Embalagem / 包装: Caixas / 箱数 {{ format_print_qty(doc.get('custom_box_count')) if doc.get('custom_box_count') is not none else '—' }} · Paletes / 托盘数 {{ format_print_qty(doc.get('custom_pallet_count')) if doc.get('custom_pallet_count') is not none else '—' }}</div>
{% set invoices = get_delivery_invoice_names(doc.name) if not doc.is_new() else [] %}<div class="block">发票: {{ invoices | join(', ') | e if invoices else 'Não faturado / 未开票' }}<br>Plano de faturação / 开票安排: {{ p.invoice_plan or '未填写具体安排' | e }}</div>
<div class="block">Diferenças / devoluções / 差异 / 退货备注: {{ doc.get('custom_delivery_notes') or '' | e }}</div><div class="block sign">Nome do cliente que recebeu / 客户签收姓名 / Nome: {{ doc.get('custom_signature_name') or '________________' | e }}<br><br>签字 / Assinatura: ____________________ 日期 / Data: {{ doc.get('custom_signature_date') or '________________' }}<br><br>Confirmação do motorista / 司机确认: ____________________ Diferenças / 差异: ____________________</div>
{% if doc.get('custom_print_color_qr') %}{% set seen = [] %}<div class="block">{% for item in p['items'] %}{% if item.template_code and item.template_code not in seen %}{% set unused = seen.append(item.template_code) %}{% set qr = get_color_card_qr_img(item.template_code) %}{% if qr %}<img class="qr" src="{{ qr | e }}">{{ item.template_code | e }} {% endif %}{% endif %}{% endfor %}</div>{% endif %}
<div id="footer-html" class="visible-pdf"><div class="text-center">{{ doc.name | e }} · <span class="page"></span> / <span class="topage"></span></div></div>

css:
@page{size:A4;margin:12mm}.print-format{font-size:var(--solua-font-size);color:#263238}h2{font-size:20px;color:#99732c}table{width:100%;border-collapse:collapse;margin:10px 0}th,td{padding:var(--solua-cell-padding);border-bottom:1px solid #ddd;vertical-align:top;overflow-wrap:normal}th{background:#f5f1e9}thead{display:table-header-group}tr{page-break-inside:avoid}.meta td{width:50%}.num{text-align:right}.photo{max-width:45px;max-height:45px}.block{page-break-inside:avoid;margin-top:12px}.sign{height:95px;border:1px solid #bbb;padding:8px}.warning{color:#a35c00}.qr{height:60px;width:60px}
.print-format table.items, .print-format table.wholesale-items { table-layout: auto; }
.print-format table.items th, .print-format table.items td,
.print-format table.wholesale-items th, .print-format table.wholesale-items td { overflow-wrap: normal; word-break: normal; }
.print-format .items .col-item { min-width: 24mm; }
.print-format .items .col-sku { min-width: 27mm; white-space: nowrap; }
.print-format .items .col-color-code, .print-format .items .col-cor { min-width: 16mm; white-space: nowrap; }
.print-format .items .col-barcode { min-width: 31mm; white-space: nowrap; }
.print-format .items .col-description { min-width: 42mm; white-space: normal; overflow-wrap: break-word; word-break: normal; }
.print-format .items .col-qty, .print-format .items .col-uom,
.print-format .items .col-rate, .print-format .items .col-amount { white-space: nowrap; }
